"""Tests for analysis config YAML linter."""

import sys
from pathlib import Path
from typing import Any

import pytest
import yaml

sys.path.insert(0, str(Path(__file__).parent))

from lint_analysis_config import (  # noqa: E402
    check_file,
    check_metric_table_keys,
    lint_config,
    normalize_equation,
)

UNIT_HEADER = {"metric": "Metric", "value": "Value", "unit": "Unit"}

UNITS_TYPO_CONFIG_TEXT = """\
# AUTOGENERATED FILE. Only edit for testing purposes, not for development.
Panel Config:
  data source:
  - metric_table:
      id: 1202
      title: LDS Statistics
      header:
        metric: Metric
        value: Value
        unit: Unit
      metric:
        LDS Bandwidth:
          value: SUM(x * 128)
          units: Gbps
"""


def make_panel_config(
    table_id: int,
    header: dict[str, str],
    metric: dict[str, Any],
    **table_extra: Any,
) -> dict[str, Any]:
    """Build a minimal Panel Config with a single metric_table."""
    table = {"id": table_id, "title": "T", "header": header, "metric": metric}
    table.update(table_extra)
    return {"Panel Config": {"data source": [{"metric_table": table}]}}


class TestCriticalCorrectness:
    """Tests for bugs that would corrupt equation semantics."""

    def test_peak_empirical_preserved(self) -> None:
        """Peak (Empirical) is a column header - space must be preserved."""
        assert normalize_equation("Peak (Empirical)") == "Peak (Empirical)"

    def test_unary_negation_preserves_semantics(self) -> None:
        """-(a + b) must stay -(a + b), not become -a + b which changes the result."""
        assert normalize_equation("-(a + b)") == "-(a + b)"
        assert normalize_equation("-(a * b)") == "-(a * b)"
        assert normalize_equation("-(a - b)") == "-(a - b)"

    def test_unknown_character_fallback(self) -> None:
        """Unknown characters cause fallback to original."""
        assert normalize_equation("a @ b") == "a @ b"
        assert normalize_equation("x & y") == "x & y"

    def test_incomplete_parse_fallback(self) -> None:
        """Trailing tokens should cause fallback, not partial parsing."""
        assert normalize_equation("a + b extra") == "a + b extra"


class TestConstantFactoring:
    """Main normalization: factor constants out of aggregations."""

    @pytest.mark.parametrize("func", ["SUM", "AVG", "MIN", "MAX"])
    def test_constant_factored_out(self, func: str) -> None:
        """SUM(x * 128) becomes 128 * SUM(x)."""
        assert normalize_equation(f"{func}(x * 128)") == f"128 * {func}(x)"
        assert normalize_equation(f"{func}(64 * x)") == f"64 * {func}(x)"

    def test_real_world_cache_bw_equation(self) -> None:
        """Actual equation from gfx115x configs."""
        input_eq = (
            "SUM(TCP_TOTAL_CACHE_ACCESSES_sum * 128) / "
            "SUM(End_Timestamp - Start_Timestamp)"
        )
        expected = (
            "128 * SUM(TCP_TOTAL_CACHE_ACCESSES_sum) / "
            "SUM(End_Timestamp - Start_Timestamp)"
        )
        assert normalize_equation(input_eq) == expected

    def test_nested_aggregations(self) -> None:
        """Each nested aggregation factors independently."""
        result = normalize_equation("SUM(x * 2) / SUM(y * 3)")
        assert result == "2 * SUM(x) / (3 * SUM(y))"

    def test_no_factoring_for_non_aggregation(self) -> None:
        """Only SUM/AVG/MIN/MAX factor, not other functions."""
        assert normalize_equation("SQRT(x * 2)") == "SQRT(x * 2)"

    def test_no_factoring_for_addition(self) -> None:
        """Only multiplication factors, not addition."""
        assert normalize_equation("SUM(x + 128)") == "SUM(x + 128)"


class TestParenthesesMinimization:
    """Remove unnecessary parens while preserving semantics."""

    def test_unnecessary_parens_removed(self) -> None:
        """Same precedence ops don't need parens."""
        assert normalize_equation("(a + b) + c") == "a + b + c"
        assert normalize_equation("(a * b) * c") == "a * b * c"

    def test_necessary_parens_preserved(self) -> None:
        """Right-associative ops need parens."""
        assert normalize_equation("a - (b - c)") == "a - (b - c)"
        assert normalize_equation("a / (b / c)") == "a / (b / c)"

    def test_precedence_parens_preserved(self) -> None:
        """Precedence parens must stay."""
        assert normalize_equation("(a + b) * c") == "(a + b) * c"
        assert normalize_equation("a * (b + c)") == "a * (b + c)"


class TestRealWorldEquations:
    """Actual equations from YAML configs."""

    def test_variable_substitution(self) -> None:
        """$variables like $wave_size work correctly."""
        eq = (
            "SUM($wave_size * SQ_INSTS_VALU_sum) / SUM(End_Timestamp - Start_Timestamp)"
        )
        result = normalize_equation(eq)
        assert "$wave_size" in result
        assert "SUM" in result

    def test_peak_value_equation(self) -> None:
        """Peak values like $L2Bw_empirical_peak * 1e9."""
        eq = "$L2Bw_empirical_peak * 1e9"
        assert normalize_equation(eq) == eq

    def test_scientific_notation(self) -> None:
        """Scientific notation works."""
        assert normalize_equation("x / 1e9") == "x / 1e9"

    def test_literal_values(self) -> None:
        """Literals are never parsed."""
        for literal in ["N/A", "None", "null", "true", "false"]:
            assert normalize_equation(literal) == literal


class TestErrorHandling:
    """Graceful error handling and fallback."""

    def test_unmatched_parentheses_fallback(self) -> None:
        """Unmatched parens return original."""
        assert normalize_equation("a + (b") == "a + (b"
        assert normalize_equation("a + b)") == "a + b)"

    def test_whitespace_normalization(self) -> None:
        """Whitespace gets normalized."""
        assert normalize_equation("a+b") == "a + b"
        assert normalize_equation("a  +  b") == "a + b"

    def test_empty_and_simple_cases(self) -> None:
        """Simple cases work."""
        assert normalize_equation("42") == "42"
        assert normalize_equation("x") == "x"
        assert normalize_equation("SUM()") == "SUM()"


class TestMetricTableKeys:
    """Metric entry keys must match the metric_table header keys."""

    def test_consistent_table_passes(self) -> None:
        data = make_panel_config(
            1201, UNIT_HEADER, {"A": {"value": "x", "unit": "Pct"}}
        )
        assert check_metric_table_keys(data) == []

    def test_units_typo_reports_missing_and_extra(self) -> None:
        """The gfx950 LDS regression: header 'unit', metric 'units'."""
        data = make_panel_config(
            1202, UNIT_HEADER, {"A": {"value": "x", "units": "Pct"}}
        )
        issues = check_metric_table_keys(data)
        assert len(issues) == 2
        assert "missing header key(s) ['unit']" in issues[0]
        assert "key(s) not in header ['units']" in issues[1]

    def test_metadata_keys_ignored(self) -> None:
        metric = {"A": {"value": "x", "unit": "Pct", "coll_level": "L", "alias": "a"}}
        assert (
            check_metric_table_keys(make_panel_config(1201, UNIT_HEADER, metric)) == []
        )

    def test_simple_box_expr_ignored(self) -> None:
        header = {"metric": "Metric", "expr": "Expr", "unit": "Unit"}
        metric = {"A": {"expr": "x", "unit": "Pct"}}
        data = make_panel_config(201, header, metric, cli_style="simple_box")
        assert check_metric_table_keys(data) == []

    def test_memory_chart_unit_exempt_only_in_panel_3(self) -> None:
        header = {"metric": "Metric", "value": "Value"}
        metric = {"A": {"value": "x", "unit": "GB/s"}}
        assert check_metric_table_keys(make_panel_config(301, header, metric)) == []
        assert (
            len(check_metric_table_keys(make_panel_config(1201, header, metric))) == 1
        )

    def test_placeholder_range_skipped(self) -> None:
        metric = {"placeholder_range": {"::_1": "$total_l2_chan"}}
        assert (
            check_metric_table_keys(make_panel_config(1801, UNIT_HEADER, metric)) == []
        )


class TestLintConfig:
    """Equation and key checks combined over a config file."""

    def test_autogenerated_skips_equations_but_not_keys(self) -> None:
        config = yaml.safe_load(UNITS_TYPO_CONFIG_TEXT)
        lint_result = lint_config(config, UNITS_TYPO_CONFIG_TEXT)
        assert lint_result.equation_issues == []
        assert len(lint_result.key_issues) == 2

    def test_fix_rewrites_equations_and_still_fails_on_keys(
        self, tmp_path: Path
    ) -> None:
        config_text = UNITS_TYPO_CONFIG_TEXT.split("\n", 1)[1]
        config_path = tmp_path / "analysis_configs" / "gfx950" / "1200_lds.yaml"
        config_path.parent.mkdir(parents=True)
        config_path.write_text(config_text, encoding="utf-8")

        is_valid, issues = check_file(config_path, fix=True)

        assert not is_valid
        assert issues[-1] == "  Fixed 1 equation(s)"
        assert "128 * SUM(x)" in config_path.read_text(encoding="utf-8")


if __name__ == "__main__":
    pytest.main([__file__, "-v"])
